SELECT "TableroSistemaPenal_5"."PAIS" AS "PAIS",   COUNT(DISTINCT "TableroSistemaPenal_5"."ID_EVENTO") AS "ctd_ID_EVENTO_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_5"."FECHA_AUDIENCIA") AS BIGINT) AS "yr_FECHA_AUDIENCIA_ok" FROM "TableroSistemaPenal_5" WHERE ("TableroSistemaPenal_5"."ILEGALIDAD_DETENCION" = cast('1' as double)) GROUP BY "TableroSistemaPenal_5"."PAIS",   "yr_FECHA_AUDIENCIA_ok";
